@import "@fontsource-variable/figtree";
@import "@fontsource-variable/fraunces";
@import "@fontsource-variable/inconsolata";

/* Light (faithful): a pale blue-white page (#f7faff), white cards, navy ink #02294b with a
   blue-grey #5c7695 for secondary text, near-black #111112 buttons, lavender #eaddfd notes.
   The hero and contact bands are a gradient from the navy through the glow (#1aa3f0) to the
   mint-teal highlight (#3fe8c8). chart-1/2 are the purple figure gradient, chart-3 the
   periwinkle rim and glow, chart-4/5 the lime and yellow ends of the rainbow rim. */
:root {
  --background: #f7faff;
  --foreground: #02294b;
  --card: #ffffff;
  --card-foreground: #02294b;
  --popover: #ffffff;
  --popover-foreground: #02294b;
  --primary: #111112;
  --primary-foreground: #ffffff;
  --secondary: #e5effe;
  --secondary-foreground: #02294b;
  --muted: #eef3fb;
  --muted-foreground: #5c7695;
  --accent: #eaddfd;
  --accent-foreground: #3d1a5c;
  --destructive: #ce4553;
  --destructive-foreground: #ffffff;
  --border: rgb(17 17 17 / 8%);
  --input: #02294b;
  --ring: #8b8bf9;
  --highlight: #3fe8c8;
  --highlight-foreground: #02294b;
  --glow: #1aa3f0;
  --chart-1: #6748d8;
  --chart-2: #b14edb;
  --chart-3: #8b8bf9;
  --chart-4: #86ef5a;
  --chart-5: #f2dc4b;
  --sidebar: #ffffff;
  --sidebar-foreground: #02294b;
  --sidebar-primary: #111112;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #eef3fb;
  --sidebar-accent-foreground: #02294b;
  --sidebar-border: rgb(17 17 17 / 8%);
  --sidebar-ring: #8b8bf9;

  --typeface-body: "Figtree Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Figtree Variable", ui-sans-serif, system-ui, sans-serif;
  /* big figures only: blocks read it as var(--typeface-serif, Georgia) so other themes fall back */
  --typeface-serif: "Fraunces Variable", Georgia, serif;
  --typeface-mono: "Inconsolata Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 1.5rem;
  --page-width: 81.375rem; /* 1246px of content + two 28px gutters */
  --page-gutter: 1.75rem;
  --section-y: 6rem;
}

/* Dark sibling: the original's footer navy (#00172e) becomes the page, a deeper navy for
   cards and bands, light blue-white ink, the same teal, cyan and periwinkle. */
.dark {
  --background: #00172e;
  --foreground: #eef5ff;
  --card: #04223f;
  --card-foreground: #eef5ff;
  --popover: #04223f;
  --popover-foreground: #eef5ff;
  --primary: #eef5ff;
  --primary-foreground: #0c1116;
  --secondary: #0a2c4d;
  --secondary-foreground: #eef5ff;
  --muted: #082846;
  --muted-foreground: #92a9c4;
  --accent: #2c1d52;
  --accent-foreground: #eaddfd;
  --destructive: #f8626e;
  --destructive-foreground: #ffffff;
  --border: rgb(255 255 255 / 12%);
  --input: rgb(238 245 255 / 55%);
  --ring: #a3a3ff;
  --highlight: #3fe8c8;
  --highlight-foreground: #02294b;
  --glow: #1aa3f0;
  --chart-1: #8d72f0;
  --chart-2: #cf7af0;
  --chart-3: #a3a3ff;
  --chart-4: #9cf27a;
  --chart-5: #f2dc4b;
  --sidebar: #04223f;
  --sidebar-foreground: #eef5ff;
  --sidebar-primary: #eef5ff;
  --sidebar-primary-foreground: #0c1116;
  --sidebar-accent: #082846;
  --sidebar-accent-foreground: #eef5ff;
  --sidebar-border: rgb(255 255 255 / 12%);
  --sidebar-ring: #a3a3ff;
}
